CREATE TABLE portal_accounts (id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,role TEXT NOT NULL CHECK(role IN ('admin','member')),password_hash TEXT,status TEXT NOT NULL DEFAULT 'invited' CHECK(status IN ('invited','active','disabled')),session_version INTEGER NOT NULL DEFAULT 0,test_account INTEGER NOT NULL DEFAULT 0,mfa_secret TEXT,mfa_enrolled INTEGER NOT NULL DEFAULT 0,mfa_counter INTEGER NOT NULL DEFAULT -1,mfa_claim TEXT,created_at INTEGER NOT NULL);
CREATE TABLE portal_sessions (token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL,session_version INTEGER NOT NULL,mfa_verified INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX portal_sessions_account ON portal_sessions(account_id);
CREATE INDEX portal_sessions_expiry ON portal_sessions(expires_at);
CREATE TABLE portal_activations (id TEXT PRIMARY KEY,account_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,used_at INTEGER,claim TEXT);
CREATE INDEX portal_activations_account ON portal_activations(account_id);
CREATE TABLE portal_throttle (key TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE TABLE portal_photos (key TEXT PRIMARY KEY,body BLOB NOT NULL,mime TEXT NOT NULL CHECK(mime IN ('image/jpeg','image/png','image/webp')),size INTEGER NOT NULL CHECK(size>0 AND size<=262144));
